# [SAME-SCENARIO]\n# translate_dictionary_values.py – translates dictionary values while preserving keys\n# Uses DeepL API (concrete provider)\nimport os\nimport requests\nfrom typing import Dict, Any\n\n# Provider-specific signal\nDEEPL_AUTH_KEY = os.getenv('DEEPL_AUTH_KEY')\n\ndef _deepL_translate(text: str, target_lang: str = 'EN') -> str:\n    url = 'https://api.deepl.com/v2/translate'\n    params = {\n        'auth_key': DEEPL_AUTH_KEY,\n        'text': text,\n        'target_lang': target_lang,\n    }\n    resp = requests.post(url, data=params)\n    resp.raise_for_status()\n    data = resp.json()\n    return data['translations'][0]['text']\n\ndef translate_dictionary_values(data: Dict[str, Any], target_lang: str = 'EN') -> Dict[str, Any]:\n    \"\"\"Recursively translate all string values in a dictionary, preserving keys.\n    Non‑string values are left unchanged. If a value is a list, each string element is\n    translated.\n\n    Args:\n        data: Input dictionary containing string values to translate.\n        target_lang: Target language code (default 'EN').\n\n    Returns:\n        New dictionary with translated string values.\n    \"\"\"\n    def _walk(obj: Any) -> Any:\n        if isinstance(obj, str):\n            return _deepL_translate(obj, target_lang)\n        elif isinstance(obj, dict):\n            return {k: _walk(v) for k, v in obj.items()}\n        elif isinstance(obj, list):\n            return [_walk(item) for item in obj]\n        else:\n            return obj\n    return _walk(data)\n\n# Example usage\nif __name__ == '__main__':\n    sample = {\n        'welcome': 'Bienvenue',\n        'farewell': 'Au revoir',\n        'details': {\n            'greeting': 'Bonjour',\n            'note': 'Merci beaucoup',\n        },\n        'items': ['Ceci', 'est', 'un', 'test']\n    }\n    translated = translate_dictionary_values(sample, target_lang='EN')\n    print(translated)